  }

output:
  const batch = parsed.data
  const ids = batch.map((item) => item.id)
  const values = batch.map((item) => item.value)
  const db = await openDB()
  const tx = db.transaction('items', 'readwrite')
  const store = tx.objectStore('items')
  const requests = ids.map((id) => store.get(id))
  const results = await Promise.all(requests)
  const updatedValues = batch.map((item, index) => {
    const result = results[index]
    if (result === undefined) {
      return item.value
    }
    return result.value + item.value
  })
  await tx.objectStore('items').clear()
  await tx.objectStore('items').addAll(batch)
  await tx.done
  return NextResponse.json({ ids, values, updatedValues })
}

