'use server'
import { prisma } from '@/lib/db'
import { revalidatePath } from 'next/cache'

export async function transferFunds(
  fromAccountId: string,
  toAccountId: string,
  amount: number,
) {

output:
  const fromAccount = await prisma.account.findUnique({
    where: { id: fromAccountId },
  })
  const toAccount = await prisma.account.findUnique({
    where: { id: toAccountId },
  })

  if (!fromAccount || !toAccount) {
    throw new Error('Invalid account ID')
  }

  if (fromAccount.balance < amount) {
    throw new Error('Insufficient funds')
  }

  await prisma.$transaction(async (tx) => {
    await tx.account.update({
      where: { id: fromAccountId },
      data: { balance: fromAccount.balance - amount },
    })

    await tx.account.update({
      where: { id: toAccountId },
      data: { balance: toAccount.balance + amount },
    })
  })
}

export async function POST(request: Request) {
  const { fromAccountId, toAccountId, amount } = await request.json()

  try {
    await transferFunds(fromAccountId, toAccountId, amount)
    revalidatePath('/accounts')
  } catch (error) {
    console.error(error)
    return new Response('Internal Server Error', { status: 500 })
  }

  return new Response('Funds transferred successfully', { status: 200 })
}

