export default function CommentThread({ postId, initialComments }: { postId: string; initialComments: Comment[] }) {

output:
  const [comments, setComments] = useState(initialComments)
  const optimisticAddComment = useOptimistic(addComment, {
    onSuccess: (comment: Comment) => {
      setComments((prevComments: Comment[]) => [...prevComments, comment])
    },
  })

  const handleAddComment = (body: string) => {
    optimisticAddComment({ postId, body })
  }

  return (
    <div>
      {comments.map((comment: Comment) => (
        <CommentItem key={comment.id} comment={comment} />
      ))}
      <AddCommentForm postId={postId} handleAddComment={handleAddComment} />
    </div>
  )
}

function CommentItem({ comment }: { comment: Comment }) {
