  for (const part of acceptLanguage.split(',')) {
    const tag = part.split(';')[0].trim().slice(0, 2)
    if (SUPPORTED_LOCALES.includes(tag as typeof SUPPORTED_LOCALES[number])) return tag
  }
  return DEFAULT_LOCALE
}

