export type CustomInputHandle = {
  focus: () => void
  clear: () => void
}

export const CustomInput = forwardRef<CustomInputHandle, { placeholder?: string }>(
  function CustomInput({ placeholder }, ref) {

output:
    const inputRef = useRef<HTMLInputElement>(null)

