      focus: () => {
        inputRef.current?.focus()
      },
      clear: () => {
        inputRef.current?.value = ''
      },
    }))

    return (
      <input
        ref={inputRef}
        placeholder={placeholder}
        autoFocus={true}
        onKeyDown={(e) => {
          if (e.key === 'Enter') {
            e.preventDefault()
            inputRef.current?.blur()
          }
        }}
      />
    )
  }
)

