          id: action.teamId,
        },
        data: {
          members: {
            create: {
              email: action.email,
              role: action.role,
            },
          },
        },
      })
      break
    case 'remove':
      await prisma.team.update({
        where: {
          id: action.teamId,
        },
        data: {
          members: {
            delete: {
              userId_teamId: {
                userId: action.userId,
                teamId: action.teamId,
              },
            },
          },
        },
      })
      break
  }
}

