  private readonly _events: Map<keyof E, unknown[]> = new Map()

  /**
   * Subscribe to an event.
   *
   * @param event - The event name.
   * @param listener - The listener function.
   * @returns A function that unsubscribes the listener.
   */
  on<K extends keyof E>(event: K, listener: (event: E[K]) => void): () => void {
    const listeners = this._events.get(event) || []
    listeners.push(listener)
    this._events.set(event, listeners)

    return () => {
      this.off(event, listener)
    }
  }

  /**
   * Unsubscribe from an event.
   *
   * @param event - The event name.
   * @param listener - The listener function.
   */
  off<K extends keyof E>(event: K, listener: (event: E[K]) => void): void {
    const listeners = this._events.get(event) || []
    const index = listeners.indexOf(listener)
    if (index !== -1) {
      listeners.splice(index, 1)
      this._events.set(event, listeners)
    }
  }

  /**
   * Emit an event.
   *
   * @param event - The event name.
   * @param event - The event payload.
   */
  emit<K extends keyof E>(event: K, event: E[K]): void {
    const listeners = this._events.get(event) || []
    for (const listener of listeners) {
      listener(event)
    }
  }
}

